sp_widget.client_script:
function ($scope, $rootScope, $timeout, spUtil, $location) {
	var c = this;

	c.captchaVerified = false;

	$scope.$on('captchaVerified', function(event, obj) {
		c.captchaVerified = obj.captchaVerified;
		c.grc = obj.grc;
		scope.$apply();
	});

	$scope.registrationInit = function(){};
}

sp_widget.css:
.text-muted {
     font-weight 500px;
  	color: $gray-dark;
}
.field-decoration-indicator{
  padding-right: 2.5px;
}
.field-decoration-indicator-text{
  margin-bottom: 25px;
}

.form_link a {
  text-decoration: underline;
}

input[type="checkbox"]:focus{
  outline-width:3px;
  outline-color:$input-border-focus;
  outline-style:solid;
}

.form_link a:focus {
  outline-width:3px;
  outline-color:$input-border-focus;
  outline-style:solid;
  outline-offset:2px;
}

.adjust-label{
  padding-top: 0px;
  margin-bottom: 7px;
}
  input:focus{
    outline-style:solid;
    outline-width:1px;
  }

@media () {
     #html_element{
         transform:scale(0.8);
         -webkit-transform:scale(0.8);
         transform-origin:0 0;
         -webkit-transform-origin:0 0;
    }
}

a{
  color : $link-color !important;
}

 input[type=text]::-ms-clear {
     display: none;
}
 input::-ms-clear {
     display: none;
}
 .exiting-username {
     padding: 10px;
     margin-bottom: 10px;
}


#reg-form{
   .text-success {
     color: $field-success-text;
   }
     .reg-header {
         height: 27px;
         font-size: 23px;
         font-weight: 500;
         line-height: 27px;
         margin-bottom: 28px;
    }
     .registration-label {
         font-size: 16px;
         line-height: 19px;
    }
     .inpt-fields {
         position: relative;
         padding: 5px;
         padding-left: 0px;
    }
     .inner-addon .glyphicon {
         position: absolute;
         padding: 10px;
         pointer-events: none;
         padding-right: 15px;
         right: 0px;
    }
     .inpt-fields input {
         padding-right: 30px;
    }
     .glyphicon {
         top: inherit;
    }
     .glyphicon-ok {
         color:$text-success;
    }
     .glyphicon-remove {
         color:$text-danger;
    }
     .has-success .form-control {
         border-color:$text-success;
    }
     .has-error .form-control {
         border-color:$text-danger;
    }
     .form-validation-rules{
         padding:15px;
         padding-bottom:10px;
         background-color: $gray-lighter;
         font-size: 14px;
    }
     .icon {
         display: table-cell;
         vertical-align: middle;
    }
     .rules-outer{
         padding-left:10px;
         padding-bottom:5px;
    }
     .rules-text {
         padding-left:10px;
         padding-right: 10px;
         display: table-cell;
         vertical-align: top;
         font-size: 14px;
         line-height: 19px;
    }
     .form-group{
         padding:5px;
    }
  
  	.form-column{
      width: 50%;
      float: left;
  	}
      .form-row:after {
      content: "";
      display: table;
      clear: both;
    }
  
     .account-existing{
         padding-top:10px;
         text-align: center;
         vertical-align: middle;
    }
     .form-link .icon{
         position:absolute;
    }
     .policy-check{
         font-size:14px;
         padding-top: 3px;
         padding-left: 15px;
    }
     .form-link{
         display:table;
         padding-left:5px;
         margin-bottom:0px;
         font-size: 16px;
         line-height: 24px;
    }
     .link-text{
         padding-left:5px;
    }
     #password-rule .fa{
         font-size:7px;
    } 
     input.ng-pristine{
         -webkit-box-shadow: none;
         -ms-box-shadow: none;
         box-shadow:none;
    }
     .form_link a {
         color: -webkit-link;
         text-decoration: underline 
    }
    .form_link a:focus {
        outline: auto -webkit-focus-ring-color !important 
    }
    input[type="checkbox"]:focus{
       outline:5px solid $input-border-focus !important;
    }
   .terms-and-conditions-text{
     margin-left: 10px;
}
   .terms-conditions-label {
     font-size: 15px;
     display: inline;
   }
 #html_element{
     transform:scale(1.05);
     -webkit-transform:scale(1.05);
     transform-origin:0 5;
     -webkit-transform-origin:0 0;
}
 @media () {
     #html_element{
         transform:scale(0.8);
         -webkit-transform:scale(0.8);
         transform-origin:0 0;
         -webkit-transform-origin:0 0;
    }
}
  
 .g-recaptcha{
   padding-bottom: 10px;
}
 #captcha_form_group{
     margin-bottom:0px;
   #captchaVerified{
     display:none;
   }
}

sp_widget.script:
(function($sp, input, data, options) {
	"use strict";
	data.is_logged_in = gs.getSession().isLoggedIn();
	data.is_logged_in = false;
	data.sys_id = '-1';
	data.captch_url= 'https://www.google.com/recaptcha/api.js?onload=onloadCallback&render=explicit&hl=' + gs.getSession().getLanguage();
	data.enableCaptcha = gs.getProperty('sn_gsm.captchaEnabled', 'true');
	data.captchaSiteKey = gs.getProperty('google.captcha.site_key');

})($sp, input, data, options);
